  assert.ok(requiredPerDay > 400 && requiredPerDay < 460, `requiredPerDay=${requiredPerDay}`);
  assert.ok(r.spec.figures.some((f) => f.includes("7,269,403")));
  assert.ok(r.spec.links.every((l) => l.expect && l.expect.length > 0));
});

